"use strict";
/* EmeraldOS Gold 1.2 - UX, Office, Staff Edition, personalization and app logic */
(function(){
const PREFIX="gold12_";
const BUILD={name:"EmeraldOS Gold 1.2",version:"1.2",cloudPath:"gold12/current"};
let z=1200, activeWin=null, fb=null, db=null;
const $=id=>document.getElementById(id);
const esc=s=>String(s??"").replace(/[&<>'"]/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;","\"":"&quot;"}[m]));
const id=()=>"g"+Math.random().toString(36).slice(2,8)+Date.now().toString(36).slice(-4);
const now=()=>new Date().toISOString();
const username=()=>localStorage.getItem("username")||localStorage.getItem("gold12_username")||"GoldUser";
const mailAddress=()=>`${username().toLowerCase().replace(/[^a-z0-9._-]/g,".")}@gold.mail`;
function read(k,f){try{return JSON.parse(localStorage.getItem(k)||JSON.stringify(f));}catch{return f;}}
function write(k,v){localStorage.setItem(k,JSON.stringify(v));return v;}
function saveText(name,text,type="text/plain"){const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function fileSize(v){return new Blob([typeof v==="string"?v:JSON.stringify(v)]).size;}
function fmtBytes(n){if(!n)return"0 B";if(n<1024)return n+" B";if(n<1048576)return(n/1024).toFixed(1)+" KB";return(n/1048576).toFixed(2)+" MB"}
function getPrefs(){return {...defaultPrefs(),...read(PREFIX+"prefs",{})};}
function setPrefs(p){write(PREFIX+"prefs",{...getPrefs(),...p});applyPrefs();saveWorkspaceDebounced();}
function defaultPrefs(){return{theme:"light",accent:"#0078d4",background:"gold-bloom",customBackground:"",bgMode:"cover",iconSize:"normal",density:"comfortable",showSearch:true,showTaskView:true,showWidgets:true,showStaff:true,showDesktopLabels:true,taskbarAlign:"left",startTiles:true,transparency:true,rounding:"small",bigText:false,reducedMotion:false,focusAssist:false,notifications:true,clockSeconds:false,desktopApps:["explorer","office","mail","settings","personalization","store","staff","dos"]};}
function defaultFiles(){return[
 {id:id(),name:"Welcome to Gold 1.2.edoc",type:"doc",folder:"Documents",star:true,content:"<h1>Welcome to EmeraldOS Gold 1.2</h1><p>This build focuses on Windows 10-inspired UX, fixed Office apps, Staff Edition, personalization, and better settings.</p>",created:now(),updated:now(),trash:false},
 {id:id(),name:"Gold Launch Checklist.etask",type:"task",folder:"Documents",star:false,content:JSON.stringify([{text:"Open Gold Office",done:false},{text:"Customize background",done:false},{text:"Test Staff Edition",done:false}]),created:now(),updated:now(),trash:false},
 {id:id(),name:"Sample Budget.esheet",type:"sheet",folder:"Sheets",star:false,content:JSON.stringify([["Item","Cost"],["Hosting","0"],["Domain","0"],["Total","=SUM(B2:B3)"]]),created:now(),updated:now(),trash:false}
];}
function files(){let f=read(PREFIX+"files",null);if(!f){f=defaultFiles();write(PREFIX+"files",f)}return f;}
function saveFiles(f){write(PREFIX+"files",f);saveWorkspaceDebounced();}
function notifs(){return read(PREFIX+"notifications",[])}
function saveNotifs(n){write(PREFIX+"notifications",n);renderNotifBadge();}
function notify(title,body,app="System",opts={}){const p=getPrefs();const n={id:id(),title,body,app,time:now(),read:false,action:opts.action||null};const arr=[n,...notifs()].slice(0,150);saveNotifs(arr);if(p.notifications!==false&&!p.focusAssist){showToast(n)}return n;}
function showToast(n){let area=document.querySelector(".toast-area");if(!area){area=document.createElement("div");area.className="toast-area";document.body.appendChild(area)}const d=document.createElement("div");d.className="toast";d.innerHTML=`<b>${esc(n.title)}</b><div>${esc(n.body)}</div><small>${esc(n.app)} · ${new Date(n.time).toLocaleTimeString()}</small>`;d.onclick=()=>{openActionCenter();d.remove()};area.appendChild(d);setTimeout(()=>d.remove(),6500)}
function renderNotifBadge(){const unread=notifs().filter(n=>!n.read).length;const b=$("actionBtn");if(b){b.textContent=unread?`🔔 ${unread}`:"🔔 0";b.classList.toggle("active",!!unread)}}
function appLogo(app,small=false){const cls=`app-logo ${app.color||"blue"}`;return `<div class="${cls}" style="--logo:${app.hex||""}">${esc(app.label||app.name.slice(0,2).toUpperCase())}</div>`}
const APPS=[
 {id:"explorer",name:"Gold Explorer",label:"EX",color:"blue",group:"Core",desc:"Files, folders, previews, Drive-like organization, sharing and restore.",open:openExplorer},
 {id:"office",name:"Gold Office",label:"OF",color:"gold",group:"Office",desc:"Fixed Docs, Sheets, Slides, Forms, templates and vault.",open:openOffice},
 {id:"mail",name:"Gold Mail",label:"ML",color:"teal",group:"Communication",desc:"Inbox, compose, drafts, sent, trash and mail notifications.",open:openMail},
 {id:"chat",name:"Gold Chat",label:"CH",color:"green",group:"Communication",desc:"Local rooms, direct messages and chat notifications.",open:openChat},
 {id:"people",name:"People",label:"PE",color:"purple",group:"Communication",desc:"Contacts, blocking, Staff contacts and user cards.",open:openPeople},
 {id:"settings",name:"Settings",label:"ST",color:"blue",group:"System",desc:"Windows 10-inspired settings with complete personalization options.",open:openSettings},
 {id:"personalization",name:"Personalization",label:"PR",color:"gold",group:"System",desc:"Themes, backgrounds, accent, taskbar, Start, and desktop.",open:openPersonalization},
 {id:"staff",name:"Gold Staff Center",label:"SF",color:"purple",group:"Staff",desc:"Staff Edition login, controls, audit, workspace and admin tools.",open:openStaffCenter},
 {id:"dos",name:"Emerald DOS",label:"ED",color:"dark",group:"System",desc:"Emerald Systems BIOS A1 DOS console inside Gold.",open:openDOS},
 {id:"store",name:"Gold Store",label:"GS",color:"green",group:"Apps",desc:"Install and test user applications with warning flow.",open:openStore},
 {id:"creator",name:"Creator Studio",label:"CS",color:"purple",group:"Apps",desc:"Create and run user apps in a safe local app runner.",open:openCreator},
 {id:"calculator",name:"Calculator",label:"CA",color:"gray",group:"Built-in",desc:"Modern calculator.",open:openCalculator},
 {id:"notepad",name:"Notepad",label:"NP",color:"blue",group:"Built-in",desc:"Quick text editor with save/export.",open:openNotepad},
 {id:"photos",name:"Photos",label:"PH",color:"pink",group:"Built-in",desc:"Image URL gallery and preview.",open:openPhotos},
 {id:"calendar",name:"Calendar",label:"CL",color:"blue",group:"Built-in",desc:"Events and agenda.",open:openCalendar},
 {id:"weather",name:"Weather",label:"WE",color:"teal",group:"Built-in",desc:"Weather-style dashboard placeholder with local notes.",open:openWeather},
 {id:"clock",name:"Alarms & Clock",label:"AC",color:"orange",group:"Built-in",desc:"Clock, timer and stopwatch.",open:openClock},
 {id:"todo",name:"Gold To Do",label:"TD",color:"green",group:"Built-in",desc:"Task list with reminders.",open:openTodo},
 {id:"sticky",name:"Sticky Notes",label:"SN",color:"gold",group:"Built-in",desc:"Desktop note cards.",open:openSticky},
 {id:"paint",name:"Gold Paint",label:"PT",color:"red",group:"Built-in",desc:"Canvas drawing board.",open:openPaint},
 {id:"snip",name:"Snip Board",label:"SB",color:"purple",group:"Built-in",desc:"Screenshot planning board and capture notes.",open:openSnip},
 {id:"voice",name:"Voice Recorder",label:"VR",color:"red",group:"Built-in",desc:"Browser audio recorder when supported.",open:openVoice},
 {id:"maps",name:"Maps",label:"MP",color:"teal",group:"Built-in",desc:"Saved places and route notes.",open:openMaps},
 {id:"news",name:"News",label:"NW",color:"red",group:"Built-in",desc:"Local bulletin board.",open:openNews},
 {id:"tips",name:"Get Started",label:"GT",color:"green",group:"Help",desc:"Tour, tips and user experience guide.",open:openTips},
 {id:"help",name:"Help + Support",label:"HP",color:"blue",group:"Help",desc:"Help articles and troubleshooting.",open:openHelp},
 {id:"restore",name:"Restore Center",label:"RS",color:"orange",group:"System",desc:"Save, restore, backup and cross-device workspace.",open:openRestore},
 {id:"updates",name:"Gold Update",label:"UP",color:"blue",group:"System",desc:"Build status, update notes and diagnostics.",open:openUpdates},
 {id:"security",name:"Security Center",label:"SC",color:"green",group:"System",desc:"Security, privacy, blocked users and app warnings.",open:openSecurity},
 {id:"feedback",name:"Feedback Hub",label:"FB",color:"purple",group:"Help",desc:"Bug reports and feature ideas.",open:openFeedback}
];
function appById(a){return APPS.find(x=>x.id===a)||APPS[0]}
function renderDesktop(){const d=$("desktop");if(!d)return;const p=getPrefs();d.innerHTML="";d.className=`desktop ${p.density||""}`;const apps=p.desktopApps.map(appById).filter(Boolean);for(const app of apps){const el=document.createElement("div");el.tabIndex=0;el.className=`desktop-icon ${p.iconSize||"normal"}`;el.innerHTML=`${appLogo(app)}${p.showDesktopLabels!==false?`<span>${esc(app.name)}</span>`:""}`;el.onclick=()=>openApp(app.id);el.onkeydown=e=>{if(e.key==="Enter")openApp(app.id)};d.appendChild(el)}}
function applyPrefs(){const p=getPrefs();document.documentElement.style.setProperty("--accent",p.accent||"#c58a00");document.documentElement.style.setProperty("--accent2",p.accent2||p.accent||"#0078d4");document.body.classList.toggle("theme-dark",p.theme==="dark");document.body.classList.toggle("theme-contrast",p.theme==="contrast");document.body.classList.toggle("theme-emerald",p.theme==="emerald");document.body.classList.toggle("theme-blue",p.theme==="blue");document.body.classList.toggle("big-text",!!p.bigText);document.body.classList.toggle("reduced-motion",!!p.reducedMotion);document.body.classList.toggle("compact",p.density==="compact");document.body.classList.toggle("bg-photo",p.background==="custom"&&!!p.customBackground);if(p.background==="custom"&&p.customBackground){document.body.style.setProperty("--custom-bg",`url(${p.customBackground})`)}else{document.body.style.removeProperty("--custom-bg")}document.documentElement.style.setProperty("--radius",p.rounding==="none"?"0px":p.rounding==="large"?"14px":"8px");if($("searchBtn"))$("searchBtn").style.display=p.showSearch===false?"none":"";if($("taskViewBtn"))$("taskViewBtn").style.display=p.showTaskView===false?"none":"";if($("widgetsBtn"))$("widgetsBtn").style.display=p.showWidgets===false?"none":"";if($("staffBtn"))$("staffBtn").style.display=p.showStaff===false?"none":"";renderDesktop();}
function saveWorkspace(){const ws={prefs:getPrefs(),files:files(),mail:read(PREFIX+"mail",defaultMail()),chat:read(PREFIX+"chat",defaultChat()),contacts:read(PREFIX+"contacts",defaultContacts()),customApps:read(PREFIX+"customApps",[]),notifs:notifs(),openWindows:[...document.querySelectorAll('.window')].map(w=>({app:w.dataset.app,title:w.dataset.title,left:w.style.left,top:w.style.top,width:w.style.width,height:w.style.height,max:w.classList.contains('max'),min:w.dataset.minimized==='true'})),updatedAt:now(),device:navigator.userAgent.slice(0,80)};write(PREFIX+"workspace",ws);saveCloudWorkspace(ws);return ws;}
let workspaceTimer=null;function saveWorkspaceDebounced(){clearTimeout(workspaceTimer);workspaceTimer=setTimeout(saveWorkspace,700)}
async function loadFirebase(){try{fb=await import("./firebase.js");db=fb.db;return fb}catch(e){console.warn("Firebase unavailable",e);return null}}
async function saveCloudWorkspace(ws){try{if(!fb) await loadFirebase();if(!fb||!db||!fb.doc||!fb.setDoc)return false;await fb.setDoc(fb.doc(db,"emeraldOSUsers",username(),"gold12","current"),ws,{merge:true});return true}catch(e){console.warn("Cloud save failed",e);return false}}
async function loadCloudWorkspace(){try{if(!fb) await loadFirebase();if(!fb||!db||!fb.doc||!fb.getDoc)return null;const snap=await fb.getDoc(fb.doc(db,"emeraldOSUsers",username(),"gold12","current"));return snap.exists()?snap.data():null}catch(e){console.warn("Cloud load failed",e);return null}}
function restoreWorkspace(ws){if(!ws)return; if(ws.prefs)write(PREFIX+"prefs",ws.prefs); if(ws.files)write(PREFIX+"files",ws.files); if(ws.mail)write(PREFIX+"mail",ws.mail); if(ws.chat)write(PREFIX+"chat",ws.chat); if(ws.contacts)write(PREFIX+"contacts",ws.contacts); if(ws.customApps)write(PREFIX+"customApps",ws.customApps); if(ws.notifs)write(PREFIX+"notifications",ws.notifs); applyPrefs();renderNotifBadge();notify("Workspace restored","Your Gold 1.2 workspace was restored.","Restore Center")}
function openApp(appId){const app=appById(appId);if(!app)return;closeFlyouts();app.open();saveRecent(appId)}
function saveRecent(appId){let r=read(PREFIX+"recent",[]).filter(x=>x!==appId);r.unshift(appId);write(PREFIX+"recent",r.slice(0,12));saveWorkspaceDebounced()}
function openWindow(appId,title,html,opt={}){let existing=opt.singleton!==false?[...document.querySelectorAll('.window')].find(w=>w.dataset.app===appId):null;if(existing){focusWindow(existing);if(existing.dataset.minimized==='true')restoreWindow(existing);return existing}const app=appById(appId);const w=document.createElement("div");w.className="window";w.dataset.app=appId;w.dataset.title=title;w.style.width=(opt.width||900)+"px";w.style.height=(opt.height||620)+"px";w.style.left=Math.max(8,Math.min(window.innerWidth-(opt.width||900)-20,opt.left||90+Math.random()*80))+"px";w.style.top=Math.max(8,Math.min(window.innerHeight-(opt.height||620)-60,opt.top||70+Math.random()*60))+"px";w.style.zIndex=++z;w.innerHTML=`<div class="win-titlebar">${appLogo(app)}<b>${esc(title)}</b><div class="win-controls"><button title="Minimize" data-act="min">—</button><button title="Maximize" data-act="max">□</button><button class="close" title="Close" data-act="close">×</button></div></div><div class="win-body"><div class="win-content">${html}</div></div><div class="resize-handle"></div>`;$("windowLayer").appendChild(w);wireWindow(w);focusWindow(w);renderTaskbarApps();saveWorkspaceDebounced();return w}
function wireWindow(w){const tb=w.querySelector(".win-titlebar");const body=w.querySelector(".win-body");tb.addEventListener("mousedown",e=>{if(e.target.closest("button"))return;focusWindow(w);if(w.classList.contains("max"))return;const sx=e.clientX,sy=e.clientY,sl=parseFloat(w.style.left),st=parseFloat(w.style.top);function mv(ev){w.style.left=Math.max(0,Math.min(window.innerWidth-80,sl+ev.clientX-sx))+"px";w.style.top=Math.max(0,Math.min(window.innerHeight-70,st+ev.clientY-sy))+"px"}function up(){removeEventListener("mousemove",mv);removeEventListener("mouseup",up);saveWorkspaceDebounced()}addEventListener("mousemove",mv);addEventListener("mouseup",up)});tb.addEventListener("dblclick",e=>{if(!e.target.closest("button"))toggleMax(w)});w.querySelector(".win-controls").addEventListener("click",e=>{const act=e.target.dataset.act;if(act==="close")closeWindow(w);if(act==="min")minimizeWindow(w);if(act==="max")toggleMax(w)});w.querySelector(".resize-handle").addEventListener("mousedown",e=>{e.preventDefault();focusWindow(w);if(w.classList.contains("max"))return;const sx=e.clientX,sy=e.clientY,sw=w.offsetWidth,sh=w.offsetHeight;function mv(ev){w.style.width=Math.max(320,sw+ev.clientX-sx)+"px";w.style.height=Math.max(220,sh+ev.clientY-sy)+"px"}function up(){removeEventListener("mousemove",mv);removeEventListener("mouseup",up);saveWorkspaceDebounced()}addEventListener("mousemove",mv);addEventListener("mouseup",up)});w.addEventListener("mousedown",()=>focusWindow(w));body.addEventListener("mousedown",e=>e.stopPropagation(),true)}
function focusWindow(w){document.querySelectorAll('.window').forEach(x=>x.classList.remove('active'));w.classList.add('active');w.style.zIndex=++z;w.dataset.minimized="false";w.style.display="";activeWin=w;renderTaskbarApps()}
function minimizeWindow(w){w.dataset.minimized="true";w.style.display="none";renderTaskbarApps();saveWorkspaceDebounced()}
function restoreWindow(w){w.dataset.minimized="false";w.style.display="";focusWindow(w);saveWorkspaceDebounced()}
function toggleMax(w){if(w.classList.contains("max")){w.classList.remove("max");const old=read(PREFIX+"win_"+w.dataset.app,null);if(old){w.style.left=old.left;w.style.top=old.top;w.style.width=old.width;w.style.height=old.height}}else{write(PREFIX+"win_"+w.dataset.app,{left:w.style.left,top:w.style.top,width:w.style.width,height:w.style.height});w.classList.add("max")}focusWindow(w);saveWorkspaceDebounced()}
function closeWindow(w){w.remove();renderTaskbarApps();saveWorkspaceDebounced()}
function renderTaskbarApps(){const bar=$("taskApps");if(!bar)return;bar.innerHTML="";[...document.querySelectorAll('.window')].forEach(w=>{const app=appById(w.dataset.app);const b=document.createElement("button");b.className="task-app"+(w.dataset.minimized==='true'?" min":"");b.innerHTML=`${appLogo(app)}<b>${esc(w.dataset.title)}</b>`;b.onclick=()=>{if(w.dataset.minimized==='true')restoreWindow(w);else focusWindow(w)};bar.appendChild(b)})}
function closeFlyouts(){["startMenu","searchPanel","taskView","actionCenter"].forEach(x=>$(x)?.classList.add("hidden"))}
function toggleStart(){const m=$("startMenu");if(!m)return;if(m.classList.contains("hidden")){renderStart();closeFlyouts();m.classList.remove("hidden")}else m.classList.add("hidden")}
function renderStart(q=""){const m=$("startMenu");const p=getPrefs();const recent=read(PREFIX+"recent",[]).map(appById).filter(Boolean);const apps=APPS.filter(a=>(a.name+a.group+a.desc).toLowerCase().includes(q.toLowerCase()));m.innerHTML=`<div class="start-rail"><button onclick="Gold12.openApp('settings')">⚙</button><button onclick="Gold12.openApp('explorer')">▣</button><button onclick="Gold12.openApp('personalization')">✎</button><button onclick="Gold12.restart()">⏻</button></div><div class="start-list"><input placeholder="Search apps, files, settings" value="${esc(q)}" oninput="Gold12.renderStart(this.value)"><h3>Recently used</h3>${recent.slice(0,5).map(a=>appRow(a)).join("")||'<p class="muted">No recent apps yet.</p>'}<h3>All apps</h3>${apps.map(a=>appRow(a)).join("")}</div><div class="start-tiles"><h3>Pinned</h3><div class="tile-grid">${["office","explorer","mail","settings","store","staff"].map(appById).map((a,i)=>`<div class="start-tile ${i%3==1?'gold':i%3==2?'green':''}" onclick="Gold12.openApp('${a.id}')">${appLogo(a)}<b>${esc(a.name)}</b><small>${esc(a.group)}</small></div>`).join("")}</div><h3>Quick actions</h3><div class="quick-actions"><button onclick="Gold12.openApp('restore')">Restore Center</button><button onclick="Gold12.openApp('dos')">Emerald DOS</button><button onclick="location.href='staff.html'">Staff Login</button><button onclick="localStorage.removeItem('gold12_setup_done');location.reload()">Setup</button></div></div>`}
function appRow(a){return `<div class="app-row" onclick="Gold12.openApp('${a.id}')">${appLogo(a)}<div><b>${esc(a.name)}</b><small>${esc(a.desc)}</small></div></div>`}
function openSearch(){closeFlyouts();const p=$("searchPanel");p.classList.remove("hidden");p.innerHTML=`<h2>Search</h2><input id="goldSearchInput" class="field" placeholder="Search apps, files, mail, settings" autofocus><div id="goldSearchResults"></div>`;const i=$("goldSearchInput"),r=$("goldSearchResults");function run(){const q=i.value.toLowerCase();let rows=[];APPS.filter(a=>(a.name+a.desc+a.group).toLowerCase().includes(q)).forEach(a=>rows.push(`<div class="app-row" onclick="Gold12.openApp('${a.id}')">${appLogo(a)}<div><b>${esc(a.name)}</b><small>App · ${esc(a.group)}</small></div></div>`));files().filter(f=>(f.name+f.folder+f.type).toLowerCase().includes(q)).forEach(f=>rows.push(`<div class="app-row" onclick="Gold12.openFile('${f.id}')"><div class="app-logo gold">${esc(fileIcon(f.type))}</div><div><b>${esc(f.name)}</b><small>File · ${esc(f.folder)}</small></div></div>`));r.innerHTML=rows.join("")||'<p class="muted">Start typing to search.</p>'}i.oninput=run;run();setTimeout(()=>i.focus(),50)}
function openTaskView(){closeFlyouts();const t=$("taskView");t.classList.remove("hidden");const wins=[...document.querySelectorAll('.window')];t.innerHTML=`<h2>Task View</h2><p class="muted">Open windows and virtual desktop tools.</p><div class="drive-grid">${wins.map(w=>`<div class="drive-card" onclick="Gold12.focusByApp('${w.dataset.app}')"><b>${esc(w.dataset.title)}</b><p>${esc(w.dataset.app)}</p><button class="btn small" onclick="event.stopPropagation();Gold12.closeByApp('${w.dataset.app}')">Close</button></div>`).join("")||'<p>No open windows.</p>'}</div><div class="toolbar"><button class="btn" onclick="Gold12.cascadeWindows()">Cascade</button><button class="btn" onclick="Gold12.tileWindows()">Tile</button><button class="btn" onclick="Gold12.restoreAllWindows()">Bring all back</button></div>`}
function focusByApp(a){const w=[...document.querySelectorAll('.window')].find(x=>x.dataset.app===a);if(w)restoreWindow(w);closeFlyouts()}
function closeByApp(a){const w=[...document.querySelectorAll('.window')].find(x=>x.dataset.app===a);if(w)closeWindow(w);openTaskView()}
function cascadeWindows(){[...document.querySelectorAll('.window')].forEach((w,i)=>{w.classList.remove('max');w.style.display="";w.dataset.minimized="false";w.style.left=40+i*28+"px";w.style.top=40+i*28+"px";w.style.width="760px";w.style.height="520px"});renderTaskbarApps()}
function tileWindows(){const wins=[...document.querySelectorAll('.window')];const cols=Math.ceil(Math.sqrt(wins.length||1)),rows=Math.ceil((wins.length||1)/cols),ww=window.innerWidth/cols,hh=(window.innerHeight-44)/rows;wins.forEach((w,i)=>{w.classList.remove('max');w.style.display="";w.dataset.minimized="false";w.style.left=(i%cols)*ww+"px";w.style.top=Math.floor(i/cols)*hh+"px";w.style.width=ww+"px";w.style.height=hh+"px"});renderTaskbarApps()}
function restoreAllWindows(){[...document.querySelectorAll('.window')].forEach(w=>{w.style.display="";w.dataset.minimized="false";if(parseFloat(w.style.left)>window.innerWidth-100)w.style.left="40px";if(parseFloat(w.style.top)>window.innerHeight-100)w.style.top="40px"});renderTaskbarApps()}
function openActionCenter(){closeFlyouts();const a=$("actionCenter");a.classList.remove("hidden");const ns=notifs();a.innerHTML=`<h2>Action Center</h2><div class="quick-actions"><button onclick="Gold12.openApp('settings')">Settings</button><button onclick="Gold12.toggleFocus()">Focus Assist</button><button onclick="Gold12.openApp('restore')">Restore</button><button onclick="Gold12.saveWorkspace();Gold12.notify('Workspace saved','Saved locally and queued for cloud sync.','Action Center')">Save Workspace</button></div><h3>Notifications</h3><div class="toolbar"><button class="btn small" onclick="Gold12.markAllRead();Gold12.openActionCenter()">Mark all read</button><button class="btn small" onclick="Gold12.clearNotifs();Gold12.openActionCenter()">Clear all</button></div>${ns.map(n=>`<div class="notif ${n.read?'':'unread'}"><b>${esc(n.title)}</b><p>${esc(n.body)}</p><small>${esc(n.app)} · ${new Date(n.time).toLocaleString()}</small></div>`).join("")||'<p class="muted">No notifications.</p>'}`}
function markAllRead(){saveNotifs(notifs().map(n=>({...n,read:true})))}function clearNotifs(){saveNotifs([])}function toggleFocus(){const p=getPrefs();setPrefs({focusAssist:!p.focusAssist});notify("Focus Assist",!p.focusAssist?"Focus Assist is now on.":"Focus Assist is now off.","Settings")}
function fileIcon(t){return({doc:"DOC",sheet:"XLS",slide:"PPT",form:"FRM",note:"TXT",task:"TSK",image:"IMG",app:"APP",folder:"DIR"}[t]||"FIL")}
function openFile(fid){const f=files().find(x=>x.id===fid);if(!f)return;if(f.type==="doc")return openOffice("docs",fid);if(f.type==="sheet")return openOffice("sheets",fid);if(f.type==="slide")return openOffice("slides",fid);if(f.type==="form")return openOffice("forms",fid);openExplorer(fid)}
function openExplorer(selected){let view=read(PREFIX+"explorerView","drive"),filter=read(PREFIX+"explorerFilter","");function render(){const all=files();const base=all.filter(f=>view==="trash"?f.trash:!f.trash);let scoped=view==="starred"?base.filter(f=>f.star):view==="recent"?[...base].sort((a,b)=>String(b.updated||b.created).localeCompare(String(a.updated||a.created))):view==="shared"?base.filter(f=>f.shared):base;const visible=scoped.filter(f=>(f.name+f.folder+f.type).toLowerCase().includes(filter.toLowerCase()));return `<div class="app-shell"><nav class="app-nav"><button class="active" onclick="Gold12.openApp('explorer')">Home</button><button onclick="Gold12.explorerView('drive')">My Drive</button><button onclick="Gold12.explorerView('recent')">Recent</button><button onclick="Gold12.explorerView('starred')">Starred</button><button onclick="Gold12.explorerView('shared')">Shared</button><button onclick="Gold12.explorerView('trash')">Trash</button><button onclick="Gold12.openApp('office')">Open Gold Office</button></nav><main class="app-main"><h2>Gold Explorer</h2><p class="muted">Drive-like file management for EmeraldOS Gold.</p><div class="toolbar"><button class="btn primary" onclick="Gold12.newFileDialog()">New</button><button class="btn" onclick="Gold12.newFolder()">New Folder</button><button class="btn" onclick="Gold12.exportAllFiles()">Export Backup</button><button class="btn" onclick="Gold12.importFilesPrompt()">Import Backup</button><input class="field" style="max-width:260px" placeholder="Search files" value="${esc(filter)}" onchange="Gold12.setExplorerFilter(this.value)"></div><div class="drive-grid">${visible.map(f=>fileCard(f)).join("")||'<p class="muted">No files here.</p>'}</div></main></div>`}
function fileCard(f){return `<div class="drive-card" onclick="Gold12.openFile('${f.id}')"><div class="type">${esc(f.type)} · ${esc(f.folder||'My Drive')}</div><h3>${f.star?'★ ':''}${esc(f.name)}</h3><p class="muted">${fmtBytes(fileSize(f.content||''))} · ${new Date(f.updated||f.created).toLocaleDateString()}</p><div class="toolbar"><button class="btn small" onclick="event.stopPropagation();Gold12.renameFile('${f.id}')">Rename</button><button class="btn small" onclick="event.stopPropagation();Gold12.starFile('${f.id}')">${f.star?'Unstar':'Star'}</button><button class="btn small" onclick="event.stopPropagation();Gold12.trashFile('${f.id}')">${f.trash?'Restore':'Trash'}</button><button class="btn small danger" onclick="event.stopPropagation();Gold12.deleteFile('${f.id}')">Delete</button></div></div>`}
const win=openWindow("explorer","Gold Explorer",render(),{width:1040,height:700});window.Gold12._rerenderExplorer=()=>{const body=win.querySelector('.win-content');if(body)body.innerHTML=render()};window.Gold12._rerenderExplorer();}
function explorerView(v){write(PREFIX+"explorerView",v);notify("Explorer",`Opened ${v}.`,"Gold Explorer");openExplorer()}
function setExplorerFilter(v){write(PREFIX+"explorerFilter",v||"");openExplorer()}
function newFileDialog(){openWindow("new-file","Create new file",`<h2>Create new file</h2><label>Name<input id="nf_name" class="field" value="Untitled.edoc"></label><label>Type<select id="nf_type" class="field"><option value="doc">Document</option><option value="sheet">Sheet</option><option value="slide">Slide</option><option value="form">Form</option><option value="note">Text note</option></select></label><label>Folder<input id="nf_folder" class="field" value="Documents"></label><button class="btn primary" onclick="Gold12.createNewFile()">Create</button>`,{width:420,height:360,singleton:false})}
function createNewFile(){const name=$("nf_name").value||"Untitled.edoc",type=$("nf_type").value,folder=$("nf_folder").value||"Documents";let content="";if(type==="doc")content="<h1>Untitled Document</h1><p>Start writing...</p>";if(type==="sheet")content=JSON.stringify([["A","B","C"],["","",""]]);if(type==="slide")content=JSON.stringify([{title:"Title",body:"Subtitle"}]);if(type==="form")content=JSON.stringify([{q:"Question",type:"short"}]);const f={id:id(),name,type,folder,star:false,content,created:now(),updated:now(),trash:false};const arr=files();arr.unshift(f);saveFiles(arr);notify("File created",name,"Gold Explorer");openFile(f.id)}
function newFolder(){const name=prompt("Folder name","New Folder");if(!name)return;const arr=files();arr.unshift({id:id(),name,type:"folder",folder:"My Drive",content:"",created:now(),updated:now(),trash:false,star:false});saveFiles(arr);notify("Folder created",name,"Gold Explorer");openExplorer()}
function renameFile(fid){const arr=files(),f=arr.find(x=>x.id===fid);if(!f)return;const name=prompt("New name",f.name);if(name){f.name=name;f.updated=now();saveFiles(arr);openExplorer();}}
function starFile(fid){const arr=files(),f=arr.find(x=>x.id===fid);if(f){f.star=!f.star;f.updated=now();saveFiles(arr);openExplorer();}}
function trashFile(fid){const arr=files(),f=arr.find(x=>x.id===fid);if(f){f.trash=!f.trash;f.updated=now();saveFiles(arr);notify(f.trash?"Moved to Trash":"Restored",f.name,"Gold Explorer");openExplorer();}}
function deleteFile(fid){if(!confirm("Delete forever?"))return;saveFiles(files().filter(f=>f.id!==fid));openExplorer();}
function exportAllFiles(){saveText("gold12-files-backup.json",JSON.stringify(files(),null,2),"application/json")}
function importFilesPrompt(){const txt=prompt("Paste exported files JSON");if(!txt)return;try{const arr=JSON.parse(txt);if(Array.isArray(arr)){saveFiles(arr);notify("Files imported",`${arr.length} files restored`,"Gold Explorer");openExplorer()}}catch(e){alert("Invalid JSON")}}
function openOffice(tab="home",fileId=null){const win=openWindow("office","Gold Office",officeHTML(tab,fileId),{width:1120,height:760});window.Gold12.renderOffice=(t,f)=>{const b=win.querySelector('.win-content');if(b)b.innerHTML=officeHTML(t,f)};window.Gold12.renderOffice(tab,fileId);}
function officeHTML(tab,fileId){const docs=files().filter(f=>["doc","sheet","slide","form"].includes(f.type)&&!f.trash);const nav=[['home','Home'],['drive','Drive'],['docs','Docs'],['sheets','Sheets'],['slides','Slides'],['forms','Forms'],['templates','Templates'],['vault','Vault']];return `<div class="app-shell"><nav class="app-nav">${nav.map(([k,n])=>`<button class="${tab===k?'active':''}" onclick="Gold12.renderOffice('${k}')">${n}</button>`).join("")}</nav><main class="app-main">${officePage(tab,fileId,docs)}</main></div>`}
function officePage(tab,fileId,docs){if(tab==="home")return `<h2>Gold Office</h2><p class="muted">A fixed Office workspace with Docs, Sheets, Slides, Forms, templates and Drive integration.</p><div class="grid4"><div class="card"><h3>New Doc</h3><button class="btn primary" onclick="Gold12.officeNew('doc')">Create</button></div><div class="card"><h3>New Sheet</h3><button class="btn primary" onclick="Gold12.officeNew('sheet')">Create</button></div><div class="card"><h3>New Slide</h3><button class="btn primary" onclick="Gold12.officeNew('slide')">Create</button></div><div class="card"><h3>New Form</h3><button class="btn primary" onclick="Gold12.officeNew('form')">Create</button></div></div><h3>Recent Office Files</h3><div class="drive-grid">${docs.slice(0,8).map(f=>officeCard(f)).join("")}</div>`;if(tab==="drive"||tab==="vault")return `<h2>Office Drive</h2><div class="toolbar"><button class="btn primary" onclick="Gold12.officeNew('doc')">New Doc</button><button class="btn" onclick="Gold12.officeNew('sheet')">New Sheet</button><button class="btn" onclick="Gold12.officeNew('slide')">New Slide</button><button class="btn" onclick="Gold12.officeNew('form')">New Form</button></div><div class="drive-grid">${docs.map(f=>officeCard(f)).join("")}</div>`;if(tab==="docs")return fileId?docEditor(fileId):officeList("doc");if(tab==="sheets")return fileId?sheetEditor(fileId):officeList("sheet");if(tab==="slides")return fileId?slideEditor(fileId):officeList("slide");if(tab==="forms")return fileId?formEditor(fileId):officeList("form");if(tab==="templates")return templatesPage();return ""}
function officeCard(f){return `<div class="drive-card" onclick="Gold12.renderOffice('${pluralTab(f.type)}','${f.id}')"><div class="type">${esc(f.type)}</div><h3>${esc(f.name)}</h3><p class="muted">${new Date(f.updated).toLocaleString()}</p></div>`}
function officeList(type){const arr=files().filter(f=>f.type===type&&!f.trash);return `<h2>${typeName(type)}</h2><div class="toolbar"><button class="btn primary" onclick="Gold12.officeNew('${type}')">New ${typeName(type)}</button></div><div class="drive-grid">${arr.map(f=>officeCard(f)).join("")||'<p class="muted">No files yet.</p>'}</div>`}
function typeName(t){return({doc:"Docs",sheet:"Sheets",slide:"Slides",form:"Forms"}[t]||t)}function pluralTab(t){return({doc:"docs",sheet:"sheets",slide:"slides",form:"forms"}[t]||"drive")}
function officeNew(type){let ext={doc:"edoc",sheet:"esheet",slide:"eslide",form:"eform"}[type];let name=prompt("Name",`Untitled.${ext}`);if(!name)return;let content="";if(type==="doc")content="<h1>Untitled</h1><p>Start writing...</p>";if(type==="sheet")content=JSON.stringify([["Item","Amount"],["",""],["Total","=SUM(B2:B2)"]]);if(type==="slide")content=JSON.stringify([{title:"Presentation Title",body:"Subtitle"}]);if(type==="form")content=JSON.stringify([{q:"Name",type:"short"},{q:"Feedback",type:"paragraph"}]);const f={id:id(),name,type,folder:typeName(type),star:false,content,created:now(),updated:now(),trash:false};const arr=files();arr.unshift(f);saveFiles(arr);notify("Office file created",name,"Gold Office");openOffice(pluralTab(type),f.id)}
function updateFile(fid,content){const arr=files();const f=arr.find(x=>x.id===fid);if(f){f.content=content;f.updated=now();saveFiles(arr);notify("Saved",f.name,"Gold Office")}}
function docEditor(fid){const f=files().find(x=>x.id===fid);return `<h2>${esc(f.name)}</h2><div class="toolbar"><button class="btn" onclick="document.execCommand('bold')"><b>B</b></button><button class="btn" onclick="document.execCommand('italic')"><i>I</i></button><button class="btn" onclick="document.execCommand('underline')"><u>U</u></button><button class="btn" onclick="document.execCommand('insertUnorderedList')">Bullets</button><button class="btn" onclick="document.execCommand('formatBlock',false,'h2')">Heading</button><button class="btn" onclick="Gold12.saveDoc('${fid}')">Save</button><button class="btn" onclick="Gold12.exportDoc('${fid}','html')">Export HTML</button><button class="btn" onclick="Gold12.exportDoc('${fid}','txt')">Export TXT</button><button class="btn" onclick="print()">Print</button></div><div id="doc_${fid}" class="editor-area" contenteditable="true">${f.content||''}</div><p class="muted">Autosave is local. Click Save to update the Drive file.</p>`}
function saveDoc(fid){const el=$("doc_"+fid);updateFile(fid,el?el.innerHTML:"")}
function exportDoc(fid,mode){const f=files().find(x=>x.id===fid);if(!f)return;const content=mode==="txt"?strip(f.content):f.content;saveText(f.name.replace(/\.[^.]+$/,mode==="txt"?".txt":".html"),content,mode==="txt"?"text/plain":"text/html")}
function strip(html){const d=document.createElement("div");d.innerHTML=html;return d.textContent||""}
function sheetEditor(fid){const f=files().find(x=>x.id===fid);let data;try{data=JSON.parse(f.content)}catch{data=[[""]]};for(let r=0;r<8;r++){data[r]=data[r]||[];for(let c=0;c<6;c++)data[r][c]=data[r][c]||""}return `<h2>${esc(f.name)}</h2><div class="toolbar"><button class="btn" onclick="Gold12.saveSheet('${fid}')">Save</button><button class="btn" onclick="Gold12.addSheetRow('${fid}')">Add Row</button><button class="btn" onclick="Gold12.exportSheet('${fid}')">Export CSV</button></div><table id="sheet_${fid}" class="sheet"><tbody>${data.map((row,r)=>`<tr>${row.map((cell,c)=>`<td contenteditable="true" data-r="${r}" data-c="${c}">${esc(evalCell(String(cell),data))}</td>`).join("")}</tr>`).join("")}</tbody></table><p class="muted">Simple formulas supported: =SUM(B2:B5), =AVG(B2:B5), =A1+B1.</p>`}
function evalCell(v,data){if(!v.startsWith("="))return v;try{if(/^=SUM\(([A-Z])(\d+):\1(\d+)\)$/i.test(v)){const m=v.match(/^=SUM\(([A-Z])(\d+):\1(\d+)\)$/i),c=m[1].toUpperCase().charCodeAt(0)-65,a=+m[2]-1,b=+m[3]-1;let s=0;for(let r=a;r<=b;r++)s+=parseFloat(data[r]?.[c])||0;return s}if(/^=AVG\(([A-Z])(\d+):\1(\d+)\)$/i.test(v)){const m=v.match(/^=AVG\(([A-Z])(\d+):\1(\d+)\)$/i),c=m[1].toUpperCase().charCodeAt(0)-65,a=+m[2]-1,b=+m[3]-1;let s=0,n=0;for(let r=a;r<=b;r++){s+=parseFloat(data[r]?.[c])||0;n++}return n?s/n:0}return v}catch{return v}}
function saveSheet(fid){const tbl=$("sheet_"+fid);const data=[...tbl.rows].map(r=>[...r.cells].map(c=>c.textContent));updateFile(fid,JSON.stringify(data))}
function addSheetRow(fid){const tbl=$("sheet_"+fid);const tr=tbl.insertRow();for(let i=0;i<6;i++){const td=tr.insertCell();td.contentEditable="true"} }
function exportSheet(fid){const tbl=$("sheet_"+fid);const csv=[...tbl.rows].map(r=>[...r.cells].map(c=>`"${c.textContent.replace(/"/g,'""')}"`).join(",")).join("\n");saveText("sheet.csv",csv,"text/csv")}
function slideEditor(fid){const f=files().find(x=>x.id===fid);let slides;try{slides=JSON.parse(f.content)}catch{slides=[{title:"Title",body:"Body"}]};let s=slides[0]||{title:"",body:""};return `<h2>${esc(f.name)}</h2><div class="toolbar"><button class="btn" onclick="Gold12.saveSlide('${fid}')">Save</button><button class="btn" onclick="Gold12.addSlide('${fid}')">Add Slide</button><button class="btn" onclick="Gold12.presentSlide('${fid}')">Present</button></div><div class="split"><div>${slides.map((x,i)=>`<div class="drive-card"><b>Slide ${i+1}</b><p>${esc(x.title)}</p></div>`).join("")}</div><div><label>Title<input id="sl_title_${fid}" class="field" value="${esc(s.title)}"></label><label>Body<textarea id="sl_body_${fid}" class="field">${esc(s.body)}</textarea></label><div class="slide-canvas"><h1>${esc(s.title)}</h1><p>${esc(s.body)}</p></div></div></div>`}
function saveSlide(fid){const f=files().find(x=>x.id===fid);let slides;try{slides=JSON.parse(f.content)}catch{slides=[{}]};slides[0]={title:$("sl_title_"+fid).value,body:$("sl_body_"+fid).value};updateFile(fid,JSON.stringify(slides))}
function addSlide(fid){const f=files().find(x=>x.id===fid);let slides=JSON.parse(f.content||"[]");slides.push({title:"New Slide",body:"Content"});updateFile(fid,JSON.stringify(slides));openOffice("slides",fid)}
function presentSlide(fid){const f=files().find(x=>x.id===fid);let slides=JSON.parse(f.content||"[]");openWindow("present","Present: "+f.name,`<div class="slide-canvas" style="min-height:500px">${slides.map(s=>`<section style="margin:30px"><h1>${esc(s.title)}</h1><p>${esc(s.body)}</p></section>`).join("")}</div>`,{width:900,height:650,singleton:false})}
function formEditor(fid){const f=files().find(x=>x.id===fid);let qs;try{qs=JSON.parse(f.content)}catch{qs=[]};return `<h2>${esc(f.name)}</h2><div class="toolbar"><button class="btn" onclick="Gold12.addFormQuestion('${fid}')">Add Question</button><button class="btn" onclick="Gold12.saveForm('${fid}')">Save</button></div><div id="form_${fid}">${qs.map((q,i)=>`<div class="card"><input class="field fq" value="${esc(q.q)}"><select class="field ft"><option value="short">Short answer</option><option value="paragraph" ${q.type==='paragraph'?'selected':''}>Paragraph</option><option value="choice" ${q.type==='choice'?'selected':''}>Multiple choice</option></select></div>`).join("")}</div><h3>Preview</h3><div class="form-preview">${qs.map(q=>`<label>${esc(q.q)}<input class="field" placeholder="${esc(q.type)}"></label>`).join("")}</div>`}
function addFormQuestion(fid){const box=$("form_"+fid);box.insertAdjacentHTML("beforeend",`<div class="card"><input class="field fq" value="New question"><select class="field ft"><option value="short">Short answer</option><option value="paragraph">Paragraph</option><option value="choice">Multiple choice</option></select></div>`)}
function saveForm(fid){const qs=[...document.querySelectorAll(`#form_${fid} .card`)].map(c=>({q:c.querySelector('.fq').value,type:c.querySelector('.ft').value}));updateFile(fid,JSON.stringify(qs))}
function templatesPage(){const t=["Business Letter","Meeting Notes","Policy","Project Proposal","Budget Sheet","Presentation Pitch","Feedback Form"];return `<h2>Templates</h2><div class="drive-grid">${t.map(x=>`<div class="drive-card"><h3>${x}</h3><p class="muted">Gold Office template</p><button class="btn primary" onclick="Gold12.useTemplate('${x}')">Use Template</button></div>`).join("")}</div>`}
function useTemplate(name){let type=name.includes("Sheet")?"sheet":name.includes("Form")?"form":name.includes("Presentation")?"slide":"doc";officeNew(type)}
function defaultMail(){return{inbox:[{id:id(),from:"system@gold.mail",to:mailAddress(),subject:"Welcome to Gold Mail",body:"Gold Mail is working in EmeraldOS Gold 1.2.",time:now(),read:false}],sent:[],drafts:[],trash:[]}}
function mail(){return read(PREFIX+"mail",defaultMail())}function saveMail(m){write(PREFIX+"mail",m);saveWorkspaceDebounced()}
function openMail(box="inbox",mid=null){const m=mail();const win=openWindow("mail","Gold Mail",mailHTML(box,mid,m),{width:1020,height:700});window.Gold12.renderMail=(b,id)=>{const body=win.querySelector('.win-content');if(body)body.innerHTML=mailHTML(b,id,mail())};window.Gold12.renderMail(box,mid)}
function mailHTML(box,mid,m){const list=m[box]||[];const msg=mid?list.find(x=>x.id===mid):null;return `<div class="app-shell"><nav class="app-nav"><button onclick="Gold12.renderMail('compose')">Compose</button>${['inbox','sent','drafts','trash'].map(b=>`<button class="${box===b?'active':''}" onclick="Gold12.renderMail('${b}')">${b[0].toUpperCase()+b.slice(1)} (${(m[b]||[]).length})</button>`).join("")}</nav><main class="app-main">${box==='compose'?composeHTML():msg?readMailHTML(box,msg):mailListHTML(box,list)}</main></div>`}
function mailListHTML(box,list){return `<h2>${box[0].toUpperCase()+box.slice(1)}</h2>${list.map(x=>`<div class="card" onclick="Gold12.renderMail('${box}','${x.id}')"><h3>${x.read?'':'● '}${esc(x.subject)}</h3><p class="muted">${esc(x.from)} → ${esc(x.to)} · ${new Date(x.time).toLocaleString()}</p><p>${esc(x.body).slice(0,160)}</p></div>`).join("")||'<p class="muted">No mail.</p>'}`}
function readMailHTML(box,msg){const mm=mail();const mmMsg=(mm[box]||[]).find(x=>x.id===msg.id);if(mmMsg){mmMsg.read=true;saveMail(mm);msg=mmMsg}return `<button class="btn" onclick="Gold12.renderMail('${box}')">Back</button><h2>${esc(msg.subject)}</h2><p class="muted">From ${esc(msg.from)} to ${esc(msg.to)} · ${new Date(msg.time).toLocaleString()}</p><div class="card"><p>${esc(msg.body).replace(/\n/g,"<br>")}</p></div><div class="toolbar"><button class="btn primary" onclick="Gold12.replyMail('${box}','${msg.id}')">Reply</button><button class="btn" onclick="Gold12.trashMail('${box}','${msg.id}')">Delete</button></div>`}
function composeHTML(to="",subject="",body=""){return `<h2>Compose</h2><label>To<input id="mail_to" class="field" value="${esc(to)}" placeholder="username@gold.mail"></label><label>Subject<input id="mail_subject" class="field" value="${esc(subject)}"></label><label>Message<textarea id="mail_body" class="field" style="height:260px">${esc(body)}</textarea></label><div class="toolbar"><button class="btn primary" onclick="Gold12.sendMail()">Send</button><button class="btn" onclick="Gold12.saveDraft()">Save Draft</button></div>`}
function sendMail(){const m=mail();const msg={id:id(),from:mailAddress(),to:$("mail_to").value,subject:$("mail_subject").value||"(No subject)",body:$("mail_body").value,time:now(),read:true};m.sent.unshift(msg);m.inbox.unshift({...msg,id:id(),from:msg.from,to:msg.to,read:false});saveMail(m);notify("Mail sent",msg.subject,"Gold Mail");openMail("sent")}
function saveDraft(){const m=mail();m.drafts.unshift({id:id(),from:mailAddress(),to:$("mail_to").value,subject:$("mail_subject").value||"Draft",body:$("mail_body").value,time:now(),read:true});saveMail(m);notify("Draft saved","Your message was saved.","Gold Mail");openMail("drafts")}
function replyMail(box,mid){const m=mail(),msg=(m[box]||[]).find(x=>x.id===mid);openMail("compose");setTimeout(()=>{$("mail_to").value=msg.from;$("mail_subject").value="Re: "+msg.subject;$("mail_body").value="\n\n--- Original ---\n"+msg.body},50)}
function trashMail(box,mid){const m=mail();const i=(m[box]||[]).findIndex(x=>x.id===mid);if(i>=0){m.trash.unshift(m[box].splice(i,1)[0]);saveMail(m);openMail(box)}}
function defaultContacts(){return[{username:"Wyatt",display:"Wyatt Monroe",mail:"wmonroe01@gold.mail",role:"Administrator",blocked:false},{username:"System",display:"Emerald Systems",mail:"system@gold.mail",role:"System",blocked:false}]}
function contacts(){return read(PREFIX+"contacts",defaultContacts())}function saveContacts(c){write(PREFIX+"contacts",c);saveWorkspaceDebounced()}
function defaultChat(){return{rooms:[{id:"general",name:"General",messages:[{id:id(),from:"System",body:"Welcome to Gold Chat.",time:now()}]}]}}
function openChat(){const c=read(PREFIX+"chat",defaultChat()),room=c.rooms[0];openWindow("chat","Gold Chat",`<div class="app-shell"><nav class="app-nav"><button class="active"># General</button><button onclick="Gold12.newChatRoom()">New room</button></nav><main class="app-main"><h2>Gold Chat</h2><div id="chatMsgs" class="card" style="height:360px;overflow:auto">${room.messages.map(m=>`<p><b>${esc(m.from)}:</b> ${esc(m.body)} <small class="muted">${new Date(m.time).toLocaleTimeString()}</small></p>`).join("")}</div><div class="toolbar"><input id="chatInput" class="field" placeholder="Message" onkeydown="if(event.key==='Enter')Gold12.sendChat()"><button class="btn primary" onclick="Gold12.sendChat()">Send</button></div></main></div>`,{width:900,height:620})}
function sendChat(){const inp=$("chatInput");if(!inp||!inp.value.trim())return;const c=read(PREFIX+"chat",defaultChat());c.rooms[0].messages.push({id:id(),from:username(),body:inp.value.trim(),time:now()});write(PREFIX+"chat",c);notify("New chat message",inp.value.trim(),"Gold Chat");openChat()}
function openPeople(){const c=contacts();openWindow("people","People",`<h2>People</h2><div class="toolbar"><button class="btn primary" onclick="Gold12.addContact()">Add Contact</button></div><div class="drive-grid">${c.map(u=>`<div class="drive-card"><h3>${esc(u.display)}</h3><p>${esc(u.username)} · ${esc(u.mail)}</p><p class="muted">${esc(u.role||'User')}</p><button class="btn small" onclick="Gold12.composeTo('${esc(u.mail)}')">Mail</button><button class="btn small" onclick="Gold12.toggleBlock('${esc(u.username)}')">${u.blocked?'Unblock':'Block'}</button></div>`).join("")}</div>`,{width:840,height:620})}
function addContact(){const name=prompt("Username");if(!name)return;const c=contacts();c.push({username:name,display:name,mail:`${name.toLowerCase()}@gold.mail`,role:"User",blocked:false});saveContacts(c);openPeople()}
function toggleBlock(user){const c=contacts();const u=c.find(x=>x.username===user);if(u){u.blocked=!u.blocked;saveContacts(c);notify(u.blocked?"User blocked":"User unblocked",u.username,"People");openPeople()}}
function composeTo(mail){openMail("compose");setTimeout(()=>{$("mail_to").value=mail},80)}
function staff(){return read(PREFIX+"staffSession",null)}function setStaff(s){write(PREFIX+"staffSession",s);$("staffBtn")?.classList.toggle("active",!!s)}
async function hash(s){const buf=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s));return Array.from(new Uint8Array(buf)).map(b=>b.toString(16).padStart(2,'0')).join('')}
async function verifyStaff(){const user=$("staff_user")?.value.trim(),pass=$("staff_pass")?.value,em=$("staff_mail")?.value.trim(),mp=$("staff_mailpass")?.value;if(!user||!pass||!em||!mp){alert("Enter EmeraldOS and Emerald Mail credentials.");return}let verified=false,role="preview";try{if(!fb)await loadFirebase();if(fb&&db&&fb.collection&&fb.getDocs){const ph=await hash(pass),mh=await hash(mp);const users=await fb.getDocs(fb.collection(db,"users"));users.forEach(doc=>{const d=doc.data();if(String(d.username||doc.id).toLowerCase()===user.toLowerCase()&&(!d.passwordHash||d.passwordHash===ph)&&["admin","moderator","mod","operator","staff","executive","owner","vip"].includes(String(d.role||"").toLowerCase())){verified=true;role=d.role||"staff"}});const mails=await fb.getDocs(fb.collection(db,"EmeraldMail"));let mailOK=false;mails.forEach(doc=>{const d=doc.data();if(String(d.email||doc.id).toLowerCase()===em.toLowerCase()&&(!d.passwordHash||d.passwordHash===mh))mailOK=true});verified=verified&&mailOK}}catch(e){console.warn(e)}if(!verified&&confirm("Firebase verification was not available or credentials were not verified. Use local Staff Preview Mode for testing?")){verified=true;role="preview"}if(verified){setStaff({username:user,mail:em,role,loginAt:now(),expiresAt:Date.now()+1000*60*60*8});notify("Staff Edition active",`Signed in as ${user}.`,"Staff Edition");openStaffCenter()}else alert("Staff verification failed.")}
function openStaffCenter(){const s=staff();openWindow("staff","Gold Staff Center",`<h2>Gold Staff Center</h2>${s?`<div class="staff-panel"><h3>Staff Edition Active</h3><p>${esc(s.username)} · ${esc(s.mail)} · ${esc(s.role)}</p></div>`:`<div class="staff-panel"><h3>Staff Edition Login</h3><p>Login with your EmeraldOS account and Emerald Mail account.</p><div class="grid2"><input id="staff_user" class="field" placeholder="EmeraldOS username"><input id="staff_pass" type="password" class="field" placeholder="EmeraldOS password"><input id="staff_mail" type="email" class="field" placeholder="Emerald Mail account"><input id="staff_mailpass" type="password" class="field" placeholder="Emerald Mail password"></div><button class="btn primary" onclick="Gold12.verifyStaff()">Login to Staff Edition</button><button class="btn" onclick="location.href='staff.html'">Open full login page</button></div>`}<h3>Staff Tools</h3><div class="grid3"><div class="card"><h3>User overview</h3><p>${contacts().length} local users/contacts.</p><button class="btn" onclick="Gold12.openApp('people')">Open People</button></div><div class="card"><h3>Workspace control</h3><button class="btn" onclick="Gold12.saveWorkspace();Gold12.notify('Staff save','Workspace saved by Staff Center.','Staff')">Save workspace</button><button class="btn" onclick="Gold12.openApp('restore')">Restore Center</button></div><div class="card"><h3>Security</h3><button class="btn" onclick="Gold12.openApp('security')">Security Center</button><button class="btn danger" onclick="Gold12.staffLogout()">Staff Logout</button></div><div class="card"><h3>System</h3><button class="btn" onclick="Gold12.openApp('dos')">Open Emerald DOS</button><button class="btn" onclick="location.href='bios.html'">Open BIOS</button></div><div class="card"><h3>Mail review</h3><p>${mail().inbox.length} inbox · ${mail().sent.length} sent · ${mail().drafts.length} drafts</p></div><div class="card"><h3>Files</h3><p>${files().length} saved file records</p><button class="btn" onclick="Gold12.openApp('explorer')">Open Explorer</button></div></div>`,{width:1000,height:720})}
function staffLogout(){localStorage.removeItem(PREFIX+"staffSession");notify("Staff Edition signed out","Staff access cleared.","Staff");openStaffCenter()}
function openSettings(page="system"){const win=openWindow("settings","Settings",settingsHTML(page),{width:1120,height:760});window.Gold12.settingsPage=(p)=>{const b=win.querySelector('.win-content');if(b)b.innerHTML=settingsHTML(p)}}
function settingsHTML(page){const nav=[['system','System'],['personal','Personalization'],['apps','Apps'],['accounts','Accounts'],['time','Time & language'],['access','Accessibility'],['privacy','Privacy'],['update','Update & Security'],['staff','Staff Edition'],['bios','BIOS & DOS']];return `<div class="settings-layout"><nav class="settings-nav">${nav.map(([k,n])=>`<button class="${page===k?'active':''}" onclick="Gold12.settingsPage('${k}')">${n}</button>`).join("")}</nav><main class="settings-page">${settingsPage(page)}</main></div>`}
function settingsPage(page){const p=getPrefs();if(page==="system")return `<h2>System</h2><div class="grid3"><div class="card"><h3>EmeraldOS Gold 1.2</h3><p>Windows 10-inspired EmeraldOS Gold experience.</p></div><div class="card"><h3>Display</h3><label>Icon size<select id="set_icon" class="field"><option>small</option><option>normal</option><option>large</option></select></label><label>Density<select id="set_density" class="field"><option>compact</option><option>comfortable</option><option>spacious</option></select></label><button class="btn primary" onclick="Gold12.saveSystemSettings()">Apply</button></div><div class="card"><h3>Storage</h3><p>${fmtBytes(fileSize(files()))} local file data</p><button class="btn" onclick="Gold12.openApp('explorer')">Open Explorer</button></div></div>`;if(page==="personal")return personalizationContent();if(page==="apps")return `<h2>Apps</h2><p>Pin or remove apps from the desktop. Apps stay available in Start.</p>${APPS.map(a=>`<label class="app-row"><span>${appLogo(a)}</span><span><b>${esc(a.name)}</b><small>${esc(a.desc)}</small></span><input type="checkbox" class="pinApp" value="${a.id}" ${p.desktopApps.includes(a.id)?'checked':''}></label>`).join("")}<button class="btn primary" onclick="Gold12.saveAppPins()">Save app pins</button>`;if(page==="accounts")return `<h2>Accounts</h2><div class="grid3"><div class="card"><h3>${esc(username())}</h3><p>EmeraldOS user</p></div><div class="card"><h3>${esc(mailAddress())}</h3><p>Gold Mail address</p></div><div class="card"><h3>${staff()?'Staff active':'Standard user'}</h3><button class="btn" onclick="Gold12.openApp('staff')">Staff Edition</button></div></div>`;if(page==="time")return `<h2>Time & language</h2><div class="grid3"><div class="card"><h3>${new Date().toLocaleTimeString()}</h3><p>Time</p></div><div class="card"><h3>${new Date().toLocaleDateString()}</h3><p>Date</p></div><div class="card"><h3>${Intl.DateTimeFormat().resolvedOptions().timeZone}</h3><p>Timezone</p></div></div>`;if(page==="access")return `<h2>Accessibility</h2><div class="grid2"><label class="card"><input id="set_big" type="checkbox" ${p.bigText?'checked':''}> Larger text</label><label class="card"><input id="set_motion" type="checkbox" ${p.reducedMotion?'checked':''}> Reduced motion</label><label class="card"><input id="set_labels" type="checkbox" ${p.showDesktopLabels!==false?'checked':''}> Desktop labels</label><div class="card"><button class="btn primary" onclick="Gold12.saveAccessSettings()">Apply Accessibility</button></div></div>`;if(page==="privacy")return `<h2>Privacy</h2><div class="grid2"><label class="card"><input id="set_notif" type="checkbox" ${p.notifications!==false?'checked':''}> Allow notifications</label><label class="card"><input id="set_focus" type="checkbox" ${p.focusAssist?'checked':''}> Focus Assist</label><div class="card"><button class="btn danger" onclick="Gold12.clearTemporaryData()">Clear temporary data</button></div><div class="card"><button class="btn" onclick="Gold12.exportWorkspace()">Export workspace</button></div></div>`;if(page==="update")return `<h2>Update & Security</h2><div class="grid3"><div class="card"><h3>Build</h3><p>${BUILD.name}</p></div><div class="card"><h3>Restore</h3><button class="btn" onclick="Gold12.openApp('restore')">Restore Center</button></div><div class="card"><h3>Reset</h3><button class="btn danger" onclick="Gold12.resetGold()">Reset Gold 1.2</button></div></div>`;if(page==="staff")return `<h2>Staff Edition</h2><p>Access Staff Edition from BIOS STAFF command, F9/F12 startup options, or Staff Center.</p><button class="btn primary" onclick="Gold12.openApp('staff')">Open Staff Center</button><button class="btn" onclick="location.href='staff.html'">Open Staff Login Page</button>`;if(page==="bios")return `<h2>BIOS & DOS</h2><p>F12 at startup opens Emerald Systems BIOS A1. DOS command STAFF opens Staff Edition.</p><button class="btn primary" onclick="location.href='bios.html'">Open BIOS / DOS</button><button class="btn" onclick="Gold12.openApp('dos')">Open In-OS Emerald DOS</button>`;return ""}
function personalizationContent(){const p=getPrefs();return `<h2>Personalization</h2><div class="grid2"><div class="card"><h3>Theme</h3><select id="set_theme" class="field"><option value="light">Gold Light</option><option value="blue">Gold Blue</option><option value="emerald">Emerald Light</option><option value="dark">Dark</option><option value="contrast">High Contrast</option></select></div><div class="card"><h3>Accent</h3><input id="set_accent" type="color" value="${esc(p.accent)}"><div class="color-swatches">${['#0078d4','#c58a00','#107c10','#5c2d91','#d13438','#008272'].map(c=>`<span class="swatch" style="background:${c}" onclick="document.getElementById('set_accent').value='${c}'"></span>`).join("")}</div></div><div class="card"><h3>Custom background</h3><input id="set_bg_url" class="field" placeholder="Image URL or data URL" value="${esc(p.customBackground||'')}"><input id="set_bg_file" type="file" accept="image/*" onchange="Gold12.loadBgFile(this)"></div><div class="card"><h3>Taskbar</h3><label><input id="set_search" type="checkbox" ${p.showSearch!==false?'checked':''}> Search box</label><br><label><input id="set_taskview" type="checkbox" ${p.showTaskView!==false?'checked':''}> Task View</label><br><label><input id="set_widgets" type="checkbox" ${p.showWidgets!==false?'checked':''}> Widgets</label><br><label><input id="set_staffbtn" type="checkbox" ${p.showStaff!==false?'checked':''}> Staff button</label></div></div><h3>Built-in backgrounds</h3><div class="bg-picker"><div class="bg-sample" style="background:linear-gradient(135deg,#f7fbff,#e8f1ff,#fbe7b5)" onclick="Gold12.chooseBg('gold-bloom')">Gold Bloom</div><div class="bg-sample" style="background:linear-gradient(135deg,#f8fbff,#dbeafe,#bfdbfe)" onclick="Gold12.chooseBg('blue')">Gold Blue</div><div class="bg-sample" style="background:linear-gradient(135deg,#f0fdf4,#d1fae5,#bbf7d0)" onclick="Gold12.chooseBg('emerald')">Emerald Light</div><div class="bg-sample" style="background:#f8fafc" onclick="Gold12.chooseBg('plain')">Plain Light</div></div><button class="btn primary" onclick="Gold12.savePersonalization()">Apply Personalization</button>`}
function openPersonalization(){openSettings("personal")}
function chooseBg(bg){setPrefs({background:bg,theme:bg==="blue"?"blue":bg==="emerald"?"emerald":getPrefs().theme});}
function loadBgFile(input){const file=input.files[0];if(!file)return;const r=new FileReader();r.onload=()=>{setPrefs({background:"custom",customBackground:r.result});notify("Background changed","Custom background applied.","Personalization")};r.readAsDataURL(file)}
function savePersonalization(){setPrefs({theme:$("set_theme")?.value||getPrefs().theme,accent:$("set_accent")?.value||getPrefs().accent,background:$("set_bg_url")?.value?"custom":getPrefs().background,customBackground:$("set_bg_url")?.value||getPrefs().customBackground,showSearch:$("set_search")?.checked,showTaskView:$("set_taskview")?.checked,showWidgets:$("set_widgets")?.checked,showStaff:$("set_staffbtn")?.checked});notify("Personalization applied","Your Gold appearance settings were saved.","Settings")}
function saveSystemSettings(){setPrefs({iconSize:$("set_icon")?.value,density:$("set_density")?.value});}
function saveAccessSettings(){setPrefs({bigText:$("set_big")?.checked,reducedMotion:$("set_motion")?.checked,showDesktopLabels:$("set_labels")?.checked});}
function saveAppPins(){setPrefs({desktopApps:[...document.querySelectorAll('.pinApp:checked')].map(x=>x.value)});notify("Desktop updated","Desktop app pins were saved.","Settings")}
function clearTemporaryData(){if(confirm("Clear temporary notifications, recent apps and local cache?")){[PREFIX+"recent",PREFIX+"notifications"].forEach(k=>localStorage.removeItem(k));renderNotifBadge();notify("Temporary data cleared","Recent activity and notifications were cleared.","Settings")}}
function exportWorkspace(){saveText("gold12-workspace.json",JSON.stringify(saveWorkspace(),null,2),"application/json")}
function resetGold(){if(confirm("Reset Gold 1.2 settings and local data?")){Object.keys(localStorage).filter(k=>k.startsWith(PREFIX)).forEach(k=>localStorage.removeItem(k));location.reload()}}
function openRestore(){openWindow("restore","Restore Center",`<h2>Restore Center</h2><div class="grid3"><div class="card"><h3>Save now</h3><button class="btn primary" onclick="Gold12.saveWorkspace();Gold12.notify('Workspace saved','Local workspace saved.','Restore Center')">Save Workspace</button></div><div class="card"><h3>Cloud restore</h3><button class="btn" onclick="Gold12.restoreCloud()">Restore from Firebase</button><button class="btn" onclick="Gold12.saveWorkspace()">Save to Firebase</button></div><div class="card"><h3>Backup</h3><button class="btn" onclick="Gold12.exportWorkspace()">Export Backup</button><button class="btn" onclick="Gold12.importWorkspacePrompt()">Import Backup</button></div></div><h3>Current workspace</h3><pre class="card">${esc(JSON.stringify(read(PREFIX+"workspace",{}),null,2)).slice(0,2000)}</pre>`,{width:900,height:650})}
async function restoreCloud(){const ws=await loadCloudWorkspace();if(ws)restoreWorkspace(ws);else alert("No cloud workspace found or Firebase unavailable.")}
function importWorkspacePrompt(){const t=prompt("Paste workspace JSON");if(!t)return;try{restoreWorkspace(JSON.parse(t))}catch{alert("Invalid JSON")}}
function openDOS(){openWindow("dos","Emerald DOS",`<div class="dos-screen"><div id="dosOut" class="dos-output">Emerald Systems BIOS A1 - Emerald DOS\nType HELP for commands.\n</div><div class="dos-line"><span>GOLD&gt;</span><input id="dosInput" onkeydown="if(event.key==='Enter')Gold12.dosRun(this)"></div></div>`,{width:760,height:480});setTimeout(()=>$("dosInput")?.focus(),80)}
function dosRun(inp){const cmd=inp.value.trim();inp.value="";const out=$("dosOut");const print=s=>{out.textContent+=`\nGOLD> ${cmd}\n${s}\n`;out.scrollTop=out.scrollHeight};const c=cmd.toUpperCase();if(c==="HELP")print("HELP VER DIR APPS STAFF SETUP RESTORE SETTINGS CLEAR TIME EXIT");else if(c==="VER")print(BUILD.name+" / Emerald Systems BIOS A1");else if(c==="DIR")print(APPS.map(a=>a.name).join("\n"));else if(c==="APPS")print(APPS.map(a=>a.id).join(" "));else if(c==="STAFF"){print("Opening Staff Edition...");location.href="staff.html"}else if(c==="SETUP"){localStorage.removeItem(PREFIX+"setup_done");location.reload()}else if(c==="RESTORE"){openRestore();print("Restore Center opened.")}else if(c==="SETTINGS"){openSettings();print("Settings opened.")}else if(c==="CLEAR"){out.textContent="Emerald DOS\n"}else if(c==="TIME")print(new Date().toString());else if(c==="EXIT"){closeByApp('dos')}else print("Unknown command. Type HELP.")}
function openStore(){openWindow("store","Gold Store",`<h2>Gold Store</h2><div class="staff-panel"><b>Security warning</b><p>Warning! By using this feature, you expose yourself to risk of infection. Use at your own risk.</p></div><div class="drive-grid"><div class="drive-card"><h3>Project Board</h3><p>User app sample</p><button class="btn primary" onclick="Gold12.installSampleApp('Project Board')">Install</button></div><div class="drive-card"><h3>Help Desk</h3><p>User app sample</p><button class="btn primary" onclick="Gold12.installSampleApp('Help Desk')">Install</button></div></div>`,{width:820,height:560})}
function installSampleApp(name){const apps=read(PREFIX+"customApps",[]);apps.push({id:id(),name,code:"api.write('<h2>"+name+"</h2><p>Installed from Gold Store.</p>'); api.button('Notify',()=>api.notify('"+name+"','Custom app works.'));"});write(PREFIX+"customApps",apps);notify("App installed",name,"Gold Store")}
function openCreator(){openWindow("creator","Creator Studio",`<h2>Creator Studio</h2><label>App name<input id="ca_name" class="field" value="My Gold App"></label><label>Code<textarea id="ca_code" class="field" style="height:240px">api.write('<h2>Hello Gold</h2><p>This custom app is running.</p>');\napi.button('Send Notification',()=>api.notify('Custom App','It works.'));</textarea></label><div class="toolbar"><button class="btn primary" onclick="Gold12.runCustomApp()">Run Preview</button><button class="btn" onclick="Gold12.saveCustomApp()">Save App</button></div><h3>Installed apps</h3>${read(PREFIX+"customApps",[]).map(a=>`<div class="app-row"><b>${esc(a.name)}</b><button class="btn small" onclick="Gold12.runSavedApp('${a.id}')">Run</button></div>`).join("")}`,{width:900,height:700})}
function saveCustomApp(){const apps=read(PREFIX+"customApps",[]);apps.push({id:id(),name:$("ca_name").value,code:$("ca_code").value});write(PREFIX+"customApps",apps);notify("Custom app saved",$("ca_name").value,"Creator Studio");openCreator()}
function runCustomApp(){runApp($("ca_name").value,$("ca_code").value)}function runSavedApp(aid){const a=read(PREFIX+"customApps",[]).find(x=>x.id===aid);if(a)runApp(a.name,a.code)}
function runApp(name,code){const html=`<div id="customApp"></div>`;const w=openWindow("custom-"+id(),name,html,{width:720,height:520,singleton:false});const root=w.querySelector('#customApp');const api={write:h=>root.insertAdjacentHTML('beforeend',h),button:(label,fn)=>{const b=document.createElement('button');b.className='btn';b.textContent=label;b.onclick=fn;root.appendChild(b)},notify:(t,b)=>notify(t,b,name),save:(k,v)=>localStorage.setItem(PREFIX+'app_'+name+'_'+k,JSON.stringify(v)),load:(k,f)=>read(PREFIX+'app_'+name+'_'+k,f),exportText:saveText};try{new Function('api',code)(api)}catch(e){root.innerHTML=`<div class="card danger-text"><b>App error</b><pre>${esc(e.stack||e.message)}</pre></div>`}}
function openCalculator(){openWindow("calculator","Calculator",`<h2>Calculator</h2><input id="calc" class="field" placeholder="2+2*5"><button class="btn primary" onclick="try{document.getElementById('calcOut').textContent=Function('return '+document.getElementById('calc').value)()}catch(e){document.getElementById('calcOut').textContent=e.message}">Calculate</button><h1 id="calcOut">0</h1>`,{width:420,height:320})}
function openNotepad(){const key=PREFIX+"notepad";openWindow("notepad","Notepad",`<h2>Notepad</h2><textarea id="np" class="field" style="height:330px">${esc(localStorage.getItem(key)||"")}</textarea><div class="toolbar"><button class="btn primary" onclick="localStorage.setItem('${key}',document.getElementById('np').value);Gold12.notify('Saved','Notepad saved.','Notepad')">Save</button><button class="btn" onclick="Gold12.saveText('notepad.txt',document.getElementById('np').value)">Export</button></div>`,{width:700,height:540})}
function simpleApp(appId,title,body){openWindow(appId,title,body,{width:760,height:540})}
function openPhotos(){simpleApp("photos","Photos",`<h2>Photos</h2><p>Paste image URLs to build a local gallery.</p><input id="photoUrl" class="field" placeholder="Image URL"><button class="btn primary" onclick="Gold12.addPhoto()">Add</button><div class="drive-grid">${read(PREFIX+"photos",[]).map(src=>`<div class="drive-card"><img src="${esc(src)}" style="max-width:100%;height:120px;object-fit:cover"></div>`).join("")}</div>`)}function addPhoto(){const url=$("photoUrl").value;if(url){const arr=read(PREFIX+"photos",[]);arr.unshift(url);write(PREFIX+"photos",arr);openPhotos()}}
function openCalendar(){simpleApp("calendar","Calendar",`<h2>Calendar</h2><input id="eventText" class="field" placeholder="Event"><button class="btn primary" onclick="Gold12.addEvent()">Add Event</button>${read(PREFIX+"events",[]).map(e=>`<div class="card"><b>${esc(e.text)}</b><p>${new Date(e.time).toLocaleString()}</p></div>`).join("")}`)}function addEvent(){const arr=read(PREFIX+"events",[]);arr.unshift({text:$("eventText").value,time:now()});write(PREFIX+"events",arr);openCalendar()}
function openWeather(){simpleApp("weather","Weather",`<h2>Weather</h2><div class="grid3"><div class="card"><h3>72°F</h3><p>Gold forecast placeholder</p></div><div class="card"><h3>Sunny</h3><p>Connect a weather API later.</p></div><div class="card"><h3>Notes</h3><textarea class="field" onchange="localStorage.setItem('${PREFIX}weatherNote',this.value)">${esc(localStorage.getItem(PREFIX+'weatherNote')||'')}</textarea></div></div>`)}
function openClock(){simpleApp("clock","Alarms & Clock",`<h2 id="bigClock">${new Date().toLocaleTimeString()}</h2><div class="toolbar"><input id="timerSec" class="field" style="max-width:160px" value="60"><button class="btn primary" onclick="Gold12.startTimer()">Start Timer</button></div><h3 id="timerOut"></h3>`);setInterval(()=>{if($("bigClock"))$("bigClock").textContent=new Date().toLocaleTimeString()},1000)}function startTimer(){let s=+$("timerSec").value||60;const out=$("timerOut");const t=setInterval(()=>{out.textContent=s+" seconds";if(s--<=0){clearInterval(t);notify("Timer done","Your timer finished.","Alarms & Clock")}},1000)}
function openTodo(){const arr=read(PREFIX+"todo",[]);simpleApp("todo","Gold To Do",`<h2>Gold To Do</h2><input id="todoText" class="field" placeholder="Task"><button class="btn primary" onclick="Gold12.addTodo()">Add</button>${arr.map((t,i)=>`<label class="card"><input type="checkbox" ${t.done?'checked':''} onchange="Gold12.toggleTodo(${i})"> ${esc(t.text)}</label>`).join("")}`)}function addTodo(){const arr=read(PREFIX+"todo",[]);arr.unshift({text:$("todoText").value,done:false});write(PREFIX+"todo",arr);openTodo()}function toggleTodo(i){const arr=read(PREFIX+"todo",[]);arr[i].done=!arr[i].done;write(PREFIX+"todo",arr)}
function openSticky(){simpleApp("sticky","Sticky Notes",`<h2>Sticky Notes</h2><textarea id="stickyText" class="field" style="height:300px">${esc(localStorage.getItem(PREFIX+'sticky')||'')}</textarea><button class="btn primary" onclick="localStorage.setItem('${PREFIX}sticky',document.getElementById('stickyText').value);Gold12.notify('Sticky Notes','Saved.','Sticky Notes')">Save</button>`)}
function openPaint(){simpleApp("paint","Gold Paint",`<h2>Gold Paint</h2><canvas id="paintCanvas" width="700" height="360" style="background:white;border:1px solid #ccc"></canvas><div class="toolbar"><input id="paintColor" type="color" value="#0078d4"><button class="btn" onclick="Gold12.clearPaint()">Clear</button></div>`);setTimeout(wirePaint,80)}function wirePaint(){const c=$("paintCanvas");if(!c)return;const ctx=c.getContext('2d');let down=false;c.onmousedown=e=>{down=true;ctx.beginPath();ctx.moveTo(e.offsetX,e.offsetY)};c.onmousemove=e=>{if(down){ctx.strokeStyle=$("paintColor").value;ctx.lineWidth=3;ctx.lineTo(e.offsetX,e.offsetY);ctx.stroke()}};c.onmouseup=()=>down=false}function clearPaint(){const c=$("paintCanvas");c.getContext('2d').clearRect(0,0,c.width,c.height)}
function openSnip(){simpleApp("snip","Snip Board",`<h2>Snip Board</h2><p>Browser security prevents direct desktop screenshots without permission, so this app saves screenshot notes and mockups.</p><textarea id="snipText" class="field" style="height:260px">${esc(localStorage.getItem(PREFIX+'snip')||'')}</textarea><button class="btn primary" onclick="localStorage.setItem('${PREFIX}snip',document.getElementById('snipText').value)">Save Snip Notes</button>`)}
function openVoice(){simpleApp("voice","Voice Recorder",`<h2>Voice Recorder</h2><p>Uses MediaRecorder when supported by the browser.</p><div class="toolbar"><button class="btn primary" onclick="Gold12.startRecording()">Start</button><button class="btn" onclick="Gold12.stopRecording()">Stop</button></div><div id="recordings"></div>`)}let rec, chunks=[];async function startRecording(){try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});chunks=[];rec=new MediaRecorder(stream);rec.ondataavailable=e=>chunks.push(e.data);rec.onstop=()=>{const blob=new Blob(chunks,{type:'audio/webm'});const url=URL.createObjectURL(blob);$("recordings").innerHTML+=`<audio controls src="${url}"></audio>`};rec.start();notify("Recording started","Voice Recorder is recording.","Voice Recorder")}catch(e){alert("Recording unavailable: "+e.message)}}function stopRecording(){if(rec)rec.stop()}
function openMaps(){simpleApp("maps","Maps",`<h2>Maps</h2><input id="place" class="field" placeholder="Saved place"><button class="btn primary" onclick="Gold12.addPlace()">Save Place</button>${read(PREFIX+'places',[]).map(p=>`<div class="card">${esc(p)}</div>`).join('')}`)}function addPlace(){const a=read(PREFIX+'places',[]);a.unshift($("place").value);write(PREFIX+'places',a);openMaps()}
function openNews(){simpleApp("news","News",`<h2>Gold News</h2><div class="card"><h3>EmeraldOS Gold 1.2 released</h3><p>Improved settings, Staff Edition, UI, Office and customization.</p></div>`)}
function openTips(){simpleApp("tips","Get Started",`<h2>Get Started with EmeraldOS Gold</h2><ol><li>Open Settings and customize your background.</li><li>Open Gold Office and create a document.</li><li>Press F12 during loading for BIOS/DOS.</li><li>Open Staff Center for Staff Edition login.</li></ol>`)}
function openHelp(){simpleApp("help","Help + Support",`<h2>Help + Support</h2><div class="grid2"><div class="card"><h3>Share files</h3><p>Use Gold Explorer and select a file.</p></div><div class="card"><h3>Use Staff Edition</h3><p>Open BIOS and type STAFF, or use the Staff app.</p></div><div class="card"><h3>Customize Gold</h3><p>Settings → Personalization.</p></div><div class="card"><h3>Restore workspace</h3><p>Use Restore Center to save, export, or restore.</p></div></div>`)}
function openUpdates(){simpleApp("updates","Gold Update",`<h2>Gold Update</h2><div class="card"><h3>${BUILD.name}</h3><p>Installed build. No external update service configured.</p></div>`)}
function openSecurity(){simpleApp("security","Security Center",`<h2>Security Center</h2><div class="grid2"><div class="card"><h3>Blocked users</h3>${contacts().filter(c=>c.blocked).map(c=>`<p>${esc(c.username)}</p>`).join('')||'<p>No blocked users.</p>'}</div><div class="card"><h3>App warnings</h3><p>User apps and store apps can be risky. Use trusted apps only.</p></div></div>`)}
function openFeedback(){simpleApp("feedback","Feedback Hub",`<h2>Feedback Hub</h2><textarea id="feedbackText" class="field" style="height:220px" placeholder="Bug or feature idea"></textarea><button class="btn primary" onclick="Gold12.submitFeedback()">Submit Feedback</button>`)}function submitFeedback(){const a=read(PREFIX+'feedback',[]);a.unshift({text:$("feedbackText").value,time:now()});write(PREFIX+'feedback',a);notify("Feedback saved","Thank you for the feedback.","Feedback Hub")}
function showSetup(){const overlay=$("setupWizard");let step=0;const steps=["Welcome","Personalize","Desktop","Staff","Finish"];function render(){overlay.classList.remove("hidden");overlay.innerHTML=`<div class="setup-card"><aside class="setup-side"><div class="gold-logo-xl" style="width:64px;height:64px;font-size:34px">G</div><h2>EmeraldOS Gold 1.2 Setup</h2><p>Set up your desktop once. You can change everything later in Settings.</p><div class="setup-steps">${steps.map((s,i)=>`<div class="${i===step?'active':''}">${i+1}. ${s}</div>`).join("")}</div></aside><main class="setup-main">${setupStep(step)}<div class="toolbar"><button class="btn" ${step===0?'disabled':''} onclick="Gold12.setupPrev()">Back</button><button class="btn primary" onclick="Gold12.setupNext()">${step===steps.length-1?'Finish':'Next'}</button><button class="btn flat" onclick="Gold12.finishSetup()">Skip</button></div></main></div>`}window.Gold12._setup={get step(){return step},set step(v){step=Math.max(0,Math.min(steps.length-1,v));render()},render};render()}
function setupStep(step){if(step===0)return `<h1>Welcome to EmeraldOS Gold</h1><p>Gold 1.2 is a Windows 10-inspired EmeraldOS edition with Office, Mail, Staff Edition, customization, and a lighter interface.</p>`;if(step===1)return `<h1>Choose a look</h1><div class="setup-choice"><div class="choice" onclick="Gold12.chooseBg('gold-bloom')">Gold Light</div><div class="choice" onclick="Gold12.chooseBg('blue')">Blue Light</div><div class="choice" onclick="Gold12.chooseBg('emerald')">Emerald Light</div><div class="choice" onclick="Gold12.chooseBg('plain')">Plain Light</div></div>`;if(step===2)return `<h1>Choose desktop apps</h1><p>Pick which apps start on the desktop.</p><div class="grid3">${['explorer','office','mail','settings','store','staff','calculator','notepad','todo'].map(x=>{const a=appById(x);return `<label class="choice"><input type="checkbox" class="setupPin" value="${a.id}" checked> ${appLogo(a)} ${esc(a.name)}</label>`}).join("")}</div>`;if(step===3)return `<h1>Staff Edition</h1><p>Staff Edition can be opened from F12 BIOS, DOS command STAFF, or the Staff app.</p><button class="btn" onclick="location.href='staff.html'">Open Staff Login</button>`;return `<h1>Ready</h1><p>Gold is ready. Setup will not appear again unless you reset it.</p>`}
function setupPrev(){Gold12._setup.step--}function setupNext(){if(Gold12._setup.step>=4)finishSetup();else Gold12._setup.step++}function finishSetup(){const pins=[...document.querySelectorAll('.setupPin:checked')].map(x=>x.value);if(pins.length)setPrefs({desktopApps:pins});localStorage.setItem(PREFIX+"setup_done","true");$("setupWizard").classList.add("hidden");notify("Setup complete","Welcome to EmeraldOS Gold 1.2.","Setup")}
function tickClock(){const c=$("clock");if(c){const d=new Date();c.innerHTML=d.toLocaleTimeString([],getPrefs().clockSeconds?{}:{hour:'2-digit',minute:'2-digit'})+"<br>"+d.toLocaleDateString([], {month:'numeric',day:'numeric'})}}
function restart(){location.reload()}
async function init(){window.Gold12=api;await loadFirebase();applyPrefs();renderNotifBadge();$("startBtn").onclick=toggleStart;$("searchBtn").onclick=openSearch;$("taskViewBtn").onclick=openTaskView;$("widgetsBtn").onclick=()=>{closeFlyouts();const p=$("searchPanel");p.classList.remove("hidden");p.innerHTML=`<h2>Widgets</h2><div class="grid2"><div class="card"><h3>Clock</h3><p>${new Date().toLocaleString()}</p></div><div class="card"><h3>Storage</h3><p>${fmtBytes(fileSize(files()))}</p></div><div class="card"><h3>Mail</h3><p>${mail().inbox.filter(m=>!m.read).length} unread</p></div><div class="card"><h3>Staff</h3><p>${staff()?'Active':'Not active'}</p></div></div>`};$("actionBtn").onclick=openActionCenter;$("staffBtn").onclick=()=>openApp('staff');setInterval(tickClock,1000);tickClock();setTimeout(()=>$("boot")?.remove(),900);if(!localStorage.getItem(PREFIX+"setup_done"))setTimeout(showSetup,1100);notify("Gold started","EmeraldOS Gold 1.2 is ready.","System");}
const api={openApp,renderStart,toggleStart,openSearch,openTaskView,focusByApp,closeByApp,cascadeWindows,tileWindows,restoreAllWindows,openActionCenter,markAllRead,clearNotifs,toggleFocus,notify,saveText,openFile,explorerView,setExplorerFilter,newFileDialog,createNewFile,newFolder,renameFile,starFile,trashFile,deleteFile,exportAllFiles,importFilesPrompt,officeNew,renderOffice:()=>{},saveDoc,exportDoc,saveSheet,addSheetRow,exportSheet,saveSlide,addSlide,presentSlide,addFormQuestion,saveForm,useTemplate,renderMail:()=>{},sendMail,saveDraft,replyMail,trashMail,addContact,toggleBlock,composeTo,verifyStaff,staffLogout,settingsPage:()=>{},savePersonalization,chooseBg,loadBgFile,saveSystemSettings,saveAccessSettings,saveAppPins,clearTemporaryData,exportWorkspace,resetGold,saveWorkspace,restoreCloud,importWorkspacePrompt,dosRun,installSampleApp,runCustomApp,saveCustomApp,runSavedApp,openPersonalization,openRestore,openDOS,runApp,startTimer,addPhoto,addEvent,addTodo,toggleTodo,startRecording,stopRecording,addPlace,submitFeedback,setupPrev,setupNext,finishSetup,restart,openOffice,openExplorer,openMail,openStaffCenter};
window.Gold12=api;window.addEventListener("DOMContentLoaded",init);window.addEventListener("resize",()=>restoreAllWindows());
})();
